CREATE UNIQUE INDEX deal_requests_one_pending_per_buyer ON public.deal_requests(buyer_id,property_id) WHERE status = 'pending';
CREATE UNIQUE INDEX transactions_one_live_per_property ON public.transactions(property_id) WHERE payment_status IN ('pending_payment','under_review','secured');
CREATE INDEX phone_otp_challenges_phone_purpose_idx ON public.phone_otp_challenges(phone,purpose,expires_at DESC);
CREATE INDEX idx_earnings_user_created ON public.earnings(user_id,created_at DESC);
CREATE INDEX idx_earnings_level ON public.earnings(user_id,level);
CREATE INDEX idx_escrow_user ON public.escrow_holds(intended_user_id,status);
CREATE INDEX idx_transactions_payment_status ON public.transactions(payment_status);
CREATE INDEX deal_requests_status_idx ON public.deal_requests(status);
CREATE INDEX messages_thread_created_idx ON public.messages(thread_id,created_at);
ALTER TABLE public.profiles ADD CONSTRAINT profiles_invited_by_fkey FOREIGN KEY(invited_by) REFERENCES public.profiles(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX profiles_matrix_slot ON public.profiles(referred_by,referral_position) WHERE referred_by IS NOT NULL;
CREATE INDEX profiles_invited_by_lookup ON public.profiles(invited_by);
ALTER TABLE public.commission_settings ADD CONSTRAINT commission_limits CHECK(sales_percent BETWEEN 0 AND 100 AND rental_percent BETWEEN 0 AND 100 AND reservation_flat>=0);
ALTER TABLE public.subscriptions ADD CONSTRAINT distribution_order CHECK(distribution_version<=activation_version);
ALTER TABLE public.subscriptions ADD CONSTRAINT paid_activation CHECK(status<>'active' OR (activation_request_id IS NOT NULL AND paid_amount IS NOT NULL AND activation_version>0));
ALTER TABLE public.deal_requests ADD CONSTRAINT deal_transaction_unique UNIQUE(transaction_id);
ALTER TABLE public.earnings ADD CONSTRAINT earnings_source CHECK((source='subscription' AND subscription_id IS NOT NULL AND transaction_id IS NULL) OR (source='transaction' AND transaction_id IS NOT NULL AND subscription_id IS NULL) OR source='referral');
ALTER TABLE public.transactions ADD CONSTRAINT transactions_receipt_unique UNIQUE(receipt_reference);
ALTER TABLE public.subscription_requests ADD CONSTRAINT subscription_receipt_unique UNIQUE(payment_reference);
ALTER TABLE public.subscription_requests ADD CONSTRAINT request_status CHECK(status IN ('pending','approved','rejected'));
ALTER TABLE public.properties ADD CONSTRAINT explicit_listing_type CHECK(status='draft' OR listing_type IS NOT NULL);
ALTER TABLE public.properties ADD CONSTRAINT listing_type_status CHECK((status<>'for_rent' OR listing_type='rental') AND (status<>'for_sale' OR listing_type='sale'));
